mapper.select:
select id, tenant_id, user_id, version_no, changed_reason, updated_at
from sys_permission_version
where tenant_id = #{tenantId}
  and user_id = #{userId}

mapper.update:
update sys_permission_version
set version_no = version_no + 1,
    changed_reason = #{changedReason},
    updated_at = now()
where tenant_id = #{tenantId}
  and user_id = #{userId}
